"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useId, useState } from "react";

import { cn } from "@/lib/utils";

/**
 * Props for a field with a floating label. Pass `value` to control it, or
 * `defaultValue` to let it hold its own text. `className` styles the wrapper;
 * every other prop reaches the `input`.
 */
export type FloatingLabelFieldProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "value" | "defaultValue" | "onChange" | "onSubmit" | "placeholder" | "children"
> & {
  label: ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Adds the trailing button. Enter in the field runs it too. */
  onSubmit?: (value: string) => void;
  /** The accessible name of the trailing button. */
  submitLabel?: string;
};

// Damping 45 is 2 × √500, rounded up: the label lands without overshoot.
const LABEL_SPRING: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
const INSTANT: Transition = { duration: 0 };
const RESTING = { y: 0, scale: 1 };
const FLOATED = { y: -11, scale: 0.75 };

/**
 * A text field whose label rests where the text will go, then moves up and
 * shrinks once the field has focus or a value. The label stays visible the
 * whole time, so it never stands in for a placeholder that disappears.
 */
export function FloatingLabelField({
  label,
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  submitLabel = "Submit",
  className,
  id,
  disabled,
  onFocus,
  onBlur,
  onKeyDown,
  ...inputProps
}: FloatingLabelFieldProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [focused, setFocused] = useState(false);
  const ownId = useId();
  const fieldId = id ?? ownId;
  const reduceMotion = useReducedMotion();
  const text = value ?? ownValue;
  const floating = focused || text !== "";

  return (
    <div
      data-floating={floating}
      className={cn(
        "relative flex h-14 w-full items-center rounded-xl border border-border bg-background",
        "has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-ring has-[input:focus-visible]:ring-offset-2 has-[input:focus-visible]:ring-offset-background",
        disabled && "opacity-50",
        className,
      )}
    >
      <input
        {...inputProps}
        id={fieldId}
        value={text}
        disabled={disabled}
        onChange={(event) => {
          if (value === undefined) setOwnValue(event.target.value);
          onValueChange?.(event.target.value);
        }}
        onFocus={(event) => {
          onFocus?.(event);
          setFocused(true);
        }}
        onBlur={(event) => {
          onBlur?.(event);
          setFocused(false);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          // Enter while an input method is composing picks a candidate; it is not a submit.
          if (event.defaultPrevented || event.key !== "Enter" || !onSubmit || event.nativeEvent.isComposing) return;
          event.preventDefault();
          onSubmit(text);
        }}
        className={cn(
          "h-full w-full min-w-0 rounded-xl bg-transparent pt-5 pb-1 pl-4 text-base text-foreground outline-none disabled:cursor-not-allowed",
          onSubmit ? "pr-14" : "pr-4",
        )}
      />
      <motion.label
        htmlFor={fieldId}
        initial={false}
        animate={floating ? FLOATED : RESTING}
        transition={reduceMotion ? INSTANT : LABEL_SPRING}
        // The label shrinks toward its left edge, so its first letter stays above the text.
        className="absolute inset-y-0 left-4 flex origin-left cursor-text items-center text-base text-muted-foreground"
      >
        {label}
      </motion.label>
      {onSubmit ? (
        <button
          type="button"
          aria-label={submitLabel}
          disabled={disabled}
          onClick={() => onSubmit(text)}
          className={cn(
            // The button is 36px; the pseudo-element grows the hit area to 44px.
            "absolute right-2.5 grid size-9 cursor-pointer touch-manipulation place-items-center rounded-full bg-primary text-primary-foreground outline-none before:absolute before:-inset-1",
            "motion-safe:transition motion-safe:duration-150 active:scale-95",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed",
          )}
        >
          <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
            <path d="M8.47 2.97 13.5 8l-5.03 5.03-1.06-1.06 3.22-3.22H2.5v-1.5h8.13L7.41 4.03l1.06-1.06Z" />
          </svg>
        </button>
      ) : null}
    </div>
  );
}
